const scrambleChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const scramble = (originalText: string) => {
    let scrambled = '';
    for (let i = 0; i < originalText.length; i++) {
        scrambled += scrambleChars[Math.floor(Math.random() * scrambleChars.length)];
    }
    return scrambled;
};

