            patternToLoad = defaultPattern;
        }

        setBeatsPerMeasure(patternToLoad.beatsPerMeasure || 4);
        setGrids(patternToLoad.grids);
        setVolumes(patternToLoad.volumes);
        setTempo(patternToLoad.tempo);
