                if (direction === 'left') {
                    const firstStep = newRow.shift();
                    if (firstStep !== undefined) {
                        newRow.push(firstStep);
                    }
                } else { // 'right'
                    const lastStep = newRow.pop();
                    if (lastStep !== undefined) {
