                        </div>
                    </Tooltip>
                </div>

                <Tooltip text="Drag to change color scheme. Click to toggle animation.">
                    <div className="flex flex-col items-center gap-2">
                        <label htmlFor="color-knob" className="font-bold text-gray-100 text-sm">
                            6 7
